// spv_embed: turns a compiled SPIR-V binary into a C++ include file holding its words.
//
//   spv_embed --name kTriangleVertSpv --source triangle.vert --compiler "shaderc v2026.4" --out triangle.vert.spv.inc in.spv
//
// The output declares `inline constexpr u32 <name>[]` and `inline constexpr usize <name>WordCount` in namespace
// engine_placeholder::shaders. It is a dev-time tool (see PLAN.md assumption #18): the generated file is committed,
// so building the engine never needs it or the shader compiler.

#include <cstdio>
#include <cstring>

#include "types.h"

using namespace engine_placeholder;

namespace {

int Usage() {
    std::fputs("usage: spv_embed --name IDENT --source FILE --compiler TEXT --out FILE input.spv\n", stderr);
    return 2;
}

bool ReadAll(const char* path, unsigned char** out, usize* size) {
    std::FILE* f = std::fopen(path, "rb");
    if (f == nullptr) {
        return false;
    }
    std::fseek(f, 0, SEEK_END);
    const long end = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (end < 0) {
        std::fclose(f);
        return false;
    }
    unsigned char* data = new unsigned char[static_cast<usize>(end) + 1];
    const usize got = std::fread(data, 1, static_cast<usize>(end), f);
    std::fclose(f);
    if (got != static_cast<usize>(end)) {
        delete[] data;
        return false;
    }
    *out = data;
    *size = got;
    return true;
}

bool IsIdentifier(const char* s) {
    if (s == nullptr || s[0] == '\0' || (s[0] >= '0' && s[0] <= '9')) {
        return false;
    }
    for (; *s != '\0'; ++s) {
        const bool ok = (*s >= 'a' && *s <= 'z') || (*s >= 'A' && *s <= 'Z') || (*s >= '0' && *s <= '9') || *s == '_';
        if (!ok) {
            return false;
        }
    }
    return true;
}

} // namespace

int main(int argc, char** argv) {
    const char* name = nullptr;
    const char* source = nullptr;
    const char* compiler = nullptr;
    const char* out_path = nullptr;
    const char* in_path = nullptr;
    for (int i = 1; i < argc; ++i) {
        const bool has_value = i + 1 < argc;
        if (std::strcmp(argv[i], "--name") == 0 && has_value) {
            name = argv[++i];
        } else if (std::strcmp(argv[i], "--source") == 0 && has_value) {
            source = argv[++i];
        } else if (std::strcmp(argv[i], "--compiler") == 0 && has_value) {
            compiler = argv[++i];
        } else if (std::strcmp(argv[i], "--out") == 0 && has_value) {
            out_path = argv[++i];
        } else if (argv[i][0] != '-' && in_path == nullptr) {
            in_path = argv[i];
        } else {
            return Usage();
        }
    }
    if (!IsIdentifier(name) || source == nullptr || compiler == nullptr || out_path == nullptr || in_path == nullptr) {
        return Usage();
    }

    unsigned char* bytes = nullptr;
    usize size = 0;
    if (!ReadAll(in_path, &bytes, &size)) {
        std::fprintf(stderr, "spv_embed: cannot read %s\n", in_path);
        return 1;
    }
    if (size == 0 || size % 4 != 0) {
        std::fprintf(stderr, "spv_embed: %s is not a whole number of 32-bit words (%zu bytes)\n", in_path, size);
        delete[] bytes;
        return 1;
    }
    const usize words = size / 4;
    auto word_at = [&](usize i) {
        return static_cast<u32>(bytes[i * 4]) | (static_cast<u32>(bytes[i * 4 + 1]) << 8) | (static_cast<u32>(bytes[i * 4 + 2]) << 16) |
               (static_cast<u32>(bytes[i * 4 + 3]) << 24);
    };
    if (word_at(0) != 0x07230203u) { // the SPIR-V magic number; this tool links only the foundation, not engine/rhi/spirv.h
        std::fprintf(stderr, "spv_embed: %s does not start with the SPIR-V magic number\n", in_path);
        delete[] bytes;
        return 1;
    }

    // Written beside the target and renamed over it, so a failed write never leaves a truncated committed file.
    char temp_path[4096];
    std::snprintf(temp_path, sizeof(temp_path), "%s.tmp", out_path);
    std::FILE* out = std::fopen(temp_path, "wb");
    if (out == nullptr) {
        std::fprintf(stderr, "spv_embed: cannot write %s\n", temp_path);
        delete[] bytes;
        return 1;
    }
    std::fprintf(out, "// Generated by tools/spv_embed from %s. Do not edit; run the `shaders` target to regenerate.\n", source);
    std::fprintf(out, "// compiler: %s\n", compiler);
    std::fputs("#pragma once\n\n#include \"types.h\"\n\nnamespace engine_placeholder::shaders {\n\n", out);
    std::fprintf(out, "inline constexpr usize %sWordCount = %zu;\n\n", name, words);
    std::fprintf(out, "inline constexpr u32 %s[%sWordCount] = {", name, name);
    for (usize i = 0; i < words; ++i) {
        std::fprintf(out, "%s0x%08x,", i % 6 == 0 ? "\n    " : " ", word_at(i));
    }
    std::fputs("\n};\n\n} // namespace engine_placeholder::shaders\n", out);
    const bool wrote = std::ferror(out) == 0;
    const bool closed = std::fclose(out) == 0;
    delete[] bytes;
    if (!wrote || !closed || std::rename(temp_path, out_path) != 0) {
        std::fprintf(stderr, "spv_embed: failed writing %s\n", out_path);
        std::remove(temp_path);
        return 1;
    }
    return 0;
}
